package com.testora.judge;
import com.testora.model.*; import java.io.*; import java.nio.charset.*; import java.nio.file.*; import java.util.*; import java.util.concurrent.*;
/** Compiles Main.java and evaluates each testcase in an isolated temp directory. */
public class JavaCompilerRunner {
 public JudgeOutcome judge(String source,Problem p,List<TestCase> tests){Path dir=null;try{dir=Files.createTempDirectory("testora-");Files.writeString(dir.resolve("Main.java"),source);Process compile=new ProcessBuilder("javac","Main.java").directory(dir.toFile()).redirectErrorStream(true).start();String msg=new String(compile.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(!compile.waitFor(15,TimeUnit.SECONDS)||compile.exitValue()!=0)return new JudgeOutcome("COMPILATION_ERROR",0,0,List.of(),msg);List<TestResult> out=new ArrayList<>();long total=0;for(TestCase tc:tests){long start=System.nanoTime();Process run=new ProcessBuilder("java","Main").directory(dir.toFile()).start();try(Writer w=new OutputStreamWriter(run.getOutputStream(),StandardCharsets.UTF_8)){w.write(tc.input()==null?"":tc.input());}boolean done=run.waitFor(p.getTimeLimitSec(),TimeUnit.SECONDS);long ms=TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start);total+=ms;String verdict;if(!done){run.destroyForcibly();verdict="TIME_LIMIT_EXCEEDED";}else if(run.exitValue()!=0){verdict="RUNTIME_ERROR";}else{String actual=new String(run.getInputStream().readAllBytes(),StandardCharsets.UTF_8).trim();verdict=actual.equals(tc.expectedOutput().trim())?"ACCEPTED":"WRONG_ANSWER";}out.add(new TestResult(tc.id(),verdict,ms));}long passed=out.stream().filter(x->x.verdict().equals("ACCEPTED")).count();String finalVerdict=passed==tests.size()?"ACCEPTED":out.stream().filter(x->x.verdict().equals("TIME_LIMIT_EXCEEDED")).findAny().isPresent()?"TIME_LIMIT_EXCEEDED":"WRONG_ANSWER";return new JudgeOutcome(finalVerdict,tests.isEmpty()?0:(double)passed*p.getMaxMarks()/tests.size(),total,out,"");}catch(Exception e){return new JudgeOutcome("RUNTIME_ERROR",0,0,List.of(),e.getMessage());}finally{if(dir!=null)delete(dir);}}
 private void delete(Path dir){try(var walk=Files.walk(dir)){walk.sorted(Comparator.reverseOrder()).forEach(x->{try{Files.deleteIfExists(x);}catch(IOException ignored){}}); }catch(IOException ignored){}}
}
